functions.score:
func score(g: GlassvowGame, c: CardInst, d: Dictionary, target: Variant, art: bool) -> float:
 var adjusted: Dictionary=d
 var debit: int=0
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="emberNova":
   debit+=mini(g.cb.embers,maxi(0,ji(fx.get("consumeEmbers",0))))
 if debit>0:
  adjusted=d.duplicate(true)
  adjusted.effects.append({"kind":"ember","n":-debit})
 return super.score(g,c,adjusted,target,art)

func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var effective: Dictionary=d
 var changed: bool=false
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("floor_per",0))!=0:
   changed=true;break
 if changed:
  effective=d.duplicate(true)
  var effects: Array=[]
  for fx: Dictionary in effective.effects:
   if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"]:
    var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
    effects.append({"kind":"dmg","n":g_payoff(stock,fx)})
   else:effects.append(fx)
  effective.effects=effects
 return super.score(g,c,effective,target,art)

functions.draft:
func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 var value: float=super.draft(g,d,id,acquire)
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("floor_per",0))!=0:
   var f: Dictionary=features(g)
   var q: float=clampf(3.0+float(f.sight)*0.7+5.0*float(f.draw)/maxf(1,float(f.size)),2,7) if fx.id=="phantom" else expected_embers(g)
   value+=float(fx.floor_per)*minf(q,float(fx.get("reserve",0)))
 return value

functions.score:
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var effective: Dictionary=d.duplicate(true)
 var converted: Array=[]
 for fx: Dictionary in effective.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="heldEmberWard":
   converted.append({"kind":"block","n":ji(fx.n)+ji(fx.per)*maxi(0,g.cb.embers-ji(fx.get("reserve",4)))})
  elif fx.get("kind")=="special" and fx.get("id")=="catalyst" and ji(fx.get("bonus",0))>0 and target!=null:
   var e: EnemyCombatant=g.cb.enemies[ji(target)];var q: int=si(e.statuses,"poison")
   converted.append({"kind":"status","who":"target","id":"poison","n":q*(ji(fx.n)-1)+ji(fx.bonus) if q>0 else 0})
  else:converted.append(fx)
 effective["effects"]=converted
 var needs_reserve: bool=false
 if not art:
  for fx: Dictionary in effective.get("effects",[]):
   if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("reserve",0))>0:
    needs_reserve=true
    break
  if needs_reserve:
   var effects: Array=[]
   for fx: Dictionary in effective.get("effects",[]):
    if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and ji(fx.get("reserve",0))>0:
     var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
     effects.append({"kind":"dmg","n":ji(fx.n)*maxi(0,stock-ji(fx.reserve))})
    else:effects.append(fx)
   effective["effects"]=effects
 return super.score(g,c,effective,target,art)

functions.draft:
func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 var effective: Dictionary=d.duplicate(true)
 var effects: Array=[]
 for fx: Dictionary in effective.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="heldEmberWard":
   effects.append({"kind":"block","n":float(fx.n)+float(fx.per)*maxf(0,expected_embers(g)-float(fx.get("reserve",4)))})
  else:effects.append(fx)
 effective["effects"]=effects
 var value: float=super.draft(g,effective,id,acquire)
 if id=="banklight" and route=="ember":value+=float(params.get("banklight_fit",12))
 for fx: Dictionary in d.get("effects",[]):
  if fx.get("kind")=="special" and fx.get("id")=="catalyst" and ji(fx.get("bonus",0))>0:
   value+=float(fx.bonus)*minf(1,float(features(g).poison)/8.0)
 return value

functions.score:
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var v: float=super.score(g,c,d,target,art)
 if params.get("bank_mode","legacy")!="current-plus-next":return v
 if copies(g,"novaflare")==0:return v
 if art:
  var spent: int=ji(g.content.arts[String(g.run.art)].get("cost",0))
  v+=spent*ember_value(g)-nova_spend_cost(g,spent)
 else:
  for fx: Dictionary in d.get("effects",[]):
   if fx.get("kind")=="special" and fx.get("id")=="emberdance":
    var f: float=pow(maxf(1,g.rules.eff_cost(g.run,g.cb,c)),0.7)
    v+=(g.cb.embers*ember_value(g)-nova_spend_cost(g,g.cb.embers))/f
 return v

functions.features:
func features(g: GlassvowGame) -> Dictionary:
 var sig: String=str(g.content.get_instance_id())+":"
 for c: CardInst in g.run.player.deck:sig+=str(c.uid)+":"+String(c.id)+":"+str(c.up)+";"
 if sig==_feature_signature:return _features
 _feature_signature=sig
 var f: Dictionary={"size":g.run.player.deck.size(),"attack":0.0,"hits":0.0,"multi":0.0,"str":0.0,"draw":0.0,"sight":0.0,"flow":0.0,"embers":0.0,"poison":0.0,"exhaust":0.0,"powers":0.0}
 for c: CardInst in g.run.player.deck:
  var d: Dictionary=card_definition(g,c)
  if str(d.get("type",""))=="power":f.powers+=1.0
  if d.get("exhaust",false):f.exhaust+=1.0
  var hits: float=0.0
  for fx: Dictionary in d.get("effects",[]):
   var n: float=float(fx.get("n",0));var kind: String=str(fx.get("kind",""))
   if kind=="dmg":hits+=float(fx.get("times",1))
   elif kind=="special" and str(fx.get("id","")) in ["momentum","phantom","emberNova","execute","leech","devour","shatterEcho"]:hits+=1.0
   elif kind=="draw" and ji(d.get("cost",0))<=1:f.draw+=n
   elif kind=="ember":f.embers+=n
   elif kind=="status":
    var sid: String=str(fx.get("id",""))
    if sid=="str" and fx.get("who")=="self":f.str+=n
    elif sid=="nightsight":f.sight+=n
    elif sid=="emberflow":f.flow+=n
    elif sid=="poison":f.poison+=n*(1.5 if fx.get("who")=="allEnemies" else 1.0)
  if hits>0:f.attack+=1.0;f.hits+=hits;f.multi+=maxf(0,hits-1)
 _features=f
 return f

functions.score:
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var value: float=super.score(g,c,d,target,art)
 var cost_factor: float=1.0 if art else pow(maxf(1,g.rules.eff_cost(g.run,g.cb,c)),0.7)
 var remaining_energy: int=g.cb.player.energy if art else g.cb.player.energy-g.rules.eff_cost(g.run,g.cb,c)
 for fx: Dictionary in d.get("effects",[]):
  var n: float=float(fx.get("n",0))
  if fx.get("kind")=="draw":
   var usable: float=4.0*(1.25 if route in ["hand","cycle"] else 1.0)*clampf(remaining_energy/1.5,0,1)
   value+=(usable-draw_value(g))*minf(n,11-g.cb.hand.size())/cost_factor
  if fx.get("kind")=="status" and fx.get("who")=="self" and fx.get("id")=="str":
   var hits: float=0
   for h: CardInst in g.cb.hand:
    if c!=null and h.uid==c.uid:continue
    for hfx: Dictionary in g.rules.card_data(h).get("effects",[]):
     if hfx.get("kind")=="dmg":hits+=float(hfx.get("times",1))
   var f: Dictionary=features(g)
   var future: float=clampf(2.0*float(f.hits)/maxf(1,float(f.attack)),2.0,8.0)
   value+=n*(minf(hits,6)+future-(7.0 if route=="fervor" else 4.5))/cost_factor
  if fx.get("kind")=="special" and fx.get("id")=="momentum":
   var remaining: float=clampf(cycle_repeats(g)-0.45*maxi(0,g.cb.turn-1),0,3)
   value+=float(fx.get("grow",0))*(remaining-minf(2,10.0/maxi(5,g.run.player.deck.size())))/cost_factor
  if fx.get("kind")=="special" and fx.get("id") in ["phantom","emberNova"] and target!=null:
   var stock: int=maxi(0,g.cb.hand.size()-1) if fx.id=="phantom" else g.cb.embers
   var reserve: int=ji(fx.get("reserve",0))
   if reserve>0:
    var e: EnemyCombatant=g.cb.enemies[ji(target)]
    var old_loss: float=maxf(0,attack_hit(g,e,int(n)*stock)-e.block)
    var new_loss: float=maxf(0,attack_hit(g,e,int(n)*maxi(0,stock-reserve))-e.block)
    value+=(minf(new_loss,e.hp)-minf(old_loss,e.hp))/cost_factor
    if old_loss>=e.hp and new_loss<e.hp:value-=(threat(g,e)*float(params.get("life",2.3))+2)/cost_factor
 if not art and si(g.cb.player.statuses,"barricade")>0:
  var pv_block: Variant=g.rules.preview_play(g.cb,c,target,g.run)
  var b: float=float(pv_block.get("block",0)) if typeof(pv_block)==TYPE_DICTIONARY else 0.0
  var unblocked: float=maxf(0,incoming(g)-g.cb.player.block)
  var carry_room: float=maxf(0,maxf(30,2*incoming(g))-maxf(g.cb.player.block,incoming(g)))
  value-=maxf(0,b-unblocked-carry_room)*0.4/cost_factor
 if not art and target!=null:
  var e: EnemyCombatant=g.cb.enemies[ji(target)]
  var pv: Variant=g.rules.preview_play(g.cb,c,target,g.run)
  if typeof(pv)==TYPE_DICTIONARY and (pv.get("lethal",false) or (g.run.aspect==0 and pv.get("willShatter",false))):
   value+=non_damage_threat(g,e)*float(params.get("disrupt",1.5))/cost_factor
 return value

functions.draft:
func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 var value: float=super.draft(g,d,id,acquire)
 if str(d.get("type","")) in ["curse","status"]:return value
 var f: Dictionary=features(g);var size: float=maxf(1,float(f.size))
 var anticipated_strength: float=minf(7,float(f.str)*0.7)
 for fx: Dictionary in d.get("effects",[]):
  var n: float=float(fx.get("n",0));var kind: String=str(fx.get("kind",""));var sid: String=str(fx.get("id",""))
  if kind=="status" and sid=="str" and fx.get("who")=="self":
   value+=n*minf(7,0.8+float(f.multi)*0.85)
  elif kind=="dmg":value+=anticipated_strength*float(fx.get("times",1))
  elif kind=="draw":
   value+=n*minf(2,copies(g,"phantomBlades")*0.6+copies(g,"momentum")*0.35)
  elif kind=="status" and sid=="nightsight":
   value+=n*minf(10,copies(g,"phantomBlades")*3+copies(g,"momentum")*2)
  elif kind=="status" and sid=="emberflow":
   value+=n*minf(10,2+copies(g,"novaflare")*4)
  elif kind=="ember":value+=n*minf(4,copies(g,"novaflare")*1.5)
  elif kind=="special":
   if sid=="momentum":
    # Replace unconditional two-growth valuation with circulation estimate.
    value+=float(fx.get("grow",0))*(0.5*maxf(0,cycle_repeats(g)-1)-2)
    value+=anticipated_strength
   elif sid=="phantom":
    var hand: float=clampf(3.0+float(f.sight)*0.7+5.0*float(f.draw)/size,2,7)
    value+=n*(maxf(0,hand-float(fx.get("reserve",0)))-4)+anticipated_strength
   elif sid=="emberNova":
    value+=n*(maxf(0,expected_embers(g)-float(fx.get("reserve",0)))-3.5)+anticipated_strength
   elif sid=="catalyst" and g.run.aspect==1:
    value+=minf(12,float(f.poison)*0.5)*(n-1)-5
 if str(d.get("type",""))=="power" and copies(g,id)>0:value-=5*copies(g,id)
 return value

functions.score:
func score(g: GlassvowGame,c: CardInst,d: Dictionary,target: Variant,art: bool) -> float:
 var p: PlayerCombatant=g.cb.player;var t: EnemyCombatant=g.cb.enemies[ji(target)] if target!=null else null
 var selected: Array[EnemyCombatant]=[]
 if str(d.get("target",""))=="allEnemies":selected=g.cb.living_enemies()
 elif t!=null:selected.append(t)
 var inc: float=incoming(g);var unblocked: float=maxf(0,inc-p.block)
 var life: float=float(params.get("life",2.3)) if unblocked<p.hp else 8.0
 var damage: Dictionary={};var extra: int=0;var block: float=0;var value: float=0;var sid: String=""
 for fx: Dictionary in d.get("effects",[]):
  var kind: String=str(fx.get("kind",""));var n: int=ji(fx.get("n",0))
  if kind=="dmg":
   for e: EnemyCombatant in selected:damage[e.idx]=float(damage.get(e.idx,0))+(n if art else attack_hit(g,e,n))*ji(fx.get("times",1))
  elif kind=="block":block+=n if art else g.rules.preview_block(g.cb,n,g.run)
  elif kind=="chip":extra+=n
  elif kind=="draw":value+=draw_value(g)*minf(n,11-g.cb.hand.size())
  elif kind=="energy":value+=n*5.5*minf(1.2,0.25+0.2*g.cb.hand.size())
  elif kind=="heal":value+=minf(n,p.max_hp-p.hp)*2
  elif kind=="loseHp":value-=n*life
  elif kind=="ember":value+=minf(n,g.cb.ember_cap-g.cb.embers)*ember_value(g)
  elif kind=="status":
   var status: String=str(fx.get("id",""));var who: String=str(fx.get("who",""))
   if who=="self":
    if status=="str":value+=n*(7 if route=="fervor" else 4.5)
    elif status=="dex":value+=n*3.5
    elif status=="regen":value+=n*minf(4,1+float(p.max_hp-p.hp)/8)
    elif status=="ritual":value+=n*5
    elif status=="metallicize":block+=n;value+=n*2
    elif status=="energized":value+=12*n
    elif status=="nightsight":value+=11*n
    elif status=="emberflow":value+=3*n*ember_value(g)
    elif status=="venomous" and g.run.aspect==1:value+=10*n
    elif status=="barricade":value+=6+maxf(0,p.block-inc)
    elif status=="vulnerable":value-=2*n
    elif status=="beacon" and g.run.aspect==0:value+=3*n
   else:
    for e: EnemyCombatant in selected:
     if status=="poison" and g.run.aspect==1:
      value+=poison_value(e,n)
      if si(e.statuses,"poison")+n>=e.hp:value+=threat(g,e)*life
     elif status=="weak":value+=threat(g,e)*0.25*life*minf(n,2)
     elif status=="vulnerable":value+=2.5*n
     elif status=="str" and n<0:value-=n*2
  elif kind=="special":
   sid=str(fx.get("id",""))
   if sid=="doubleBlock":block+=p.block
   elif sid=="flawless":block+=n*(2 if g.cb.hp_lost==0 else 1)
   elif sid=="emberdance":block+=n*g.cb.embers;value-=g.cb.embers*ember_value(g)
   elif sid=="pyreTithe":
    value+=ji(fx.get("draw",0))*draw_value(g)+maxi(0,g.cb.hand.size()-1)*ember_value(g)
    for h: CardInst in g.cb.hand:
     if c==null or h.uid!=c.uid:value-=maxf(0,draft(g,g.rules.card_data(h),String(h.id),false))*0.2
   elif t!=null:
    var raw: int=n
    if sid=="execute" and si(t.statuses,"vulnerable")>0:raw+=ji(fx.get("bonus",0))
    elif sid=="momentum":raw+=c.bonus;value+=ji(fx.get("grow",0))*minf(2,10.0/maxi(5,g.run.player.deck.size()))
    elif sid=="phantom":raw*=maxi(0,g.cb.hand.size()-1)
    elif sid=="emberNova":raw*=g.cb.embers
    elif sid=="shatterEcho" and (t.staggered or si(t.statuses,"vulnerable")>0):raw*=2
    elif sid=="catalyst":
     if g.run.aspect==1:
      var added: int=si(t.statuses,"poison")*(n-1);value+=poison_value(t,added)
      if si(t.statuses,"poison")+added>=t.hp:value+=threat(g,t)*life
     raw=0
    if raw>0:
     damage[t.idx]=float(damage.get(t.idx,0))+attack_hit(g,t,raw)
     if sid=="leech":value+=minf(maxf(0,float(damage[t.idx])-t.block)*0.5,p.max_hp-p.hp)*1.5
 for e: EnemyCombatant in selected:
  var loss: float=maxf(0,float(damage.get(e.idx,0))-e.block);value+=minf(loss,e.hp)
  var chips: int=extra
  if str(d.get("type",""))=="attack" and loss>0:chips+=1+ji(d.get("chip",0))+si(p.statuses,"beacon")
  if g.run.aspect!=0:chips=0
  if loss>=e.hp:value+=threat(g,e)*life+2+(8 if sid=="devour" else 0)
  elif chips>0:
   if e.chips+chips>=e.facet_max:
    if not e.staggered:value+=threat(g,e)*life
    value+=4+(3 if route=="facet" else 0)
   else:value+=chips*(2.3 if route=="facet" else 0.7)
 value+=minf(block,unblocked)*life
 if si(p.statuses,"barricade")>0:value+=maxf(0,block-unblocked)*0.4
 if not art:
  value/=pow(maxf(1,g.rules.eff_cost(g.run,g.cb,c)),0.7)
  if d.get("exhaust",false) and str(d.get("type",""))!="power":value+=ember_value(g)
 return value

functions.draft:
func draft(g: GlassvowGame,d: Dictionary,id: String,acquire: bool=true) -> float:
 if str(d.get("type","")) in ["curse","status"]:return -30
 var v: float=-2.0*ji(d.get("cost",0))
 for fx: Dictionary in d.get("effects",[]):
  var n: int=ji(fx.get("n",0));var kind: String=str(fx.get("kind",""))
  if kind=="dmg":v+=n*ji(fx.get("times",1))*(1.4 if str(d.get("target",""))=="allEnemies" else 1)
  elif kind=="block":v+=n*0.9
  elif kind=="heal":v+=n*2
  elif kind=="draw":v+=n*4
  elif kind=="energy":v+=n*4
  elif kind=="loseHp":v-=n*1.5
  elif kind=="ember":v+=n*(3.5 if route=="ember" else 2)
  elif kind=="chip":v+=n*(4 if g.run.aspect==0 else 0)
  elif kind=="status":
   var sid: String=str(fx.get("id",""))
   if sid=="poison":v+=n*(3 if g.run.aspect==1 else 0)
   elif sid=="str":v+=n*3.5 if str(fx.get("who",""))=="self" else -n*2.5
   elif sid in ["dex","metallicize"]:v+=n*3
   elif sid=="regen":v+=n*5
   elif sid in ["weak","vulnerable"]:v+=n*2*(2 if str(fx.get("who",""))=="allEnemies" else 1)
   elif sid=="ritual":v+=n*6
   elif sid in ["nightsight","energized","barricade"]:v+=14
   elif sid=="emberflow":v+=10*n
   elif sid=="venomous" and g.run.aspect==1:v+=14
  elif kind=="special":
   var sid: String=str(fx.get("id",""))
   v+=float({"leech":n*1.7,"execute":n+ji(fx.get("bonus",0))*0.5,"momentum":n+ji(fx.get("grow",0))*2,"phantom":n*4.0,"devour":n+8,"catalyst":10 if g.run.aspect==1 else -10,"shatterEcho":n*1.6,"emberNova":n*3.5,"doubleBlock":9,"flawless":n*1.4,"pyreTithe":9,"emberdance":9}.get(sid,0))
 v+=ji(d.get("chip",0))*(4 if g.run.aspect==0 else 0)
 var fit: float=float(FIT.get(route,{}).get(id,0))
 if str(d.get("type",""))=="power" and copies(g,id)>=2:fit*=0.3
 v+=fit*float(params.get("fit",1))
 if acquire:
  var n: int=copies(g,id);v-=maxi(0,n-1)*3
  if route=="cycle" and id!="momentum" and n>=2:v-=6
 return v

